    @Test
    fun testMultipleScores() {
        Assert.assertEquals(91, findMax(intArrayOf(45, 72, 38, 91, 55)))
    }

    @Test
    fun testSingleElement() {
        Assert.assertEquals(10, findMax(intArrayOf(10)))
    }

    @Test
    fun testAllSame() {
        Assert.assertEquals(5, findMax(intArrayOf(5, 5, 5)))
    }
